   <main>
     <section class="preference-card" aria-labelledby="page-title">
       <p class="eyebrow">Preferences</p>
       <h1 id="page-title">Stay in the loop</h1>
       <p class="intro">Choose the notification channel that works best for you.</p>

       <form id="notification-form">
         <div class="form-field">
           <fieldset>
             <legend>How do you prefer to receive notifications?</legend>
             <div class="radio-options">
               <label class="radio-option">
                 <input type="radio" name="notificationPreference" value="Email" required>
                 <span>Email</span>
               </label>
               <label class="radio-option">
                 <input type="radio" name="notificationPreference" value="SMS">
                 <span>SMS</span>
               </label>
               <label class="radio-option">
                 <input type="radio" name="notificationPreference" value="Push Notifications">
                 <span>Push Notifications</span>
               </label>
             </div>
           </fieldset>
         </div>

         <button type="submit">Save preference</button>
         <p class="status" id="form-status" role="status" aria-live="polite"></p>
       </form>
     </section>
   </main>

   <script>
     const form = document.querySelector("#notification-form");
     const status = document.querySelector("#form-status");

     form.addEventListener("submit", (event) => {
